// NULL-tolerant scan buffer for routineGroupScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type routineGroupPreloadBuf struct {
	ID                          null.Val[uuid.UUID]
	RoutineID                   null.Val[uuid.UUID]
	Position                    null.Val[int32]
	Mode                        null.Val[enums.RoutineGroupMode]
	RestBetweenExercisesSeconds null.Val[int32]
	RestBetweenRoundsSeconds    null.Val[int32]
	CreatedAt                   null.Val[time.Time]
}

// routineGroupScanMapperNullable maps the preloaded routineGroup
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func routineGroupScanMapperNullable(prefix string) scan.Mapper[*RoutineGroup] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*RoutineGroup, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *routineGroupPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.ID }})
			case "routine_id":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.RoutineID }})
			case "position":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.Position }})
			case "mode":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.Mode }})
			case "rest_between_exercises_seconds":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.RestBetweenExercisesSeconds }})
			case "rest_between_rounds_seconds":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.RestBetweenRoundsSeconds }})
			case "created_at":
				targets = append(targets, target{i, func(b *routineGroupPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(routineGroupPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*RoutineGroup, error) {
				buf := link.(*routineGroupPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.RoutineID.IsValue()) &&
					!(buf.Position.IsValue()) &&
					!(buf.Mode.IsValue()) &&
					!(buf.RestBetweenExercisesSeconds.IsValue()) &&
					!(buf.RestBetweenRoundsSeconds.IsValue()) &&
					!(buf.CreatedAt.IsValue()) {
					return nil, nil
				}

				o := new(RoutineGroup)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.RoutineID.IsValue() {
					o.RoutineID = buf.RoutineID.MustGet()
				}
				if buf.Position.IsValue() {
					o.Position = buf.Position.MustGet()
				}
				if buf.Mode.IsValue() {
					o.Mode = buf.Mode.MustGet()
				}
				if buf.RestBetweenExercisesSeconds.IsValue() {
					o.RestBetweenExercisesSeconds = buf.RestBetweenExercisesSeconds.MustGet()
				}
				if buf.RestBetweenRoundsSeconds.IsValue() {
					o.RestBetweenRoundsSeconds = buf.RestBetweenRoundsSeconds.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *RoutineGroup) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GroupExercisesRoutines":
		rels, ok := retrieved.(ExercisesRoutineSlice)
		if !ok {
			return fmt.Errorf("routineGroup cannot load %T as %q", retrieved, name)
		}

		o.R.GroupExercisesRoutines = rels
		o.R.Loaded.GroupExercisesRoutines = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.GroupRoutineGroup = o
				rel.R.Loaded.GroupRoutineGroup = true
			}
		}
		return nil
	case "Routine":
		rel, ok := retrieved.(*Routine)
		if !ok {
			return fmt.Errorf("routineGroup cannot load %T as %q", retrieved, name)
		}

		o.R.Routine = rel
		o.R.Loaded.Routine = true

		if rel != nil {
			rel.R.RoutineGroups = RoutineGroupSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("routineGroup has no relationship %q", name)
	}
}

