func (os RoutineGroupSlice) LoadGroupExercisesRoutines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	exercisesRoutines, err := os.GroupExercisesRoutines(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.GroupExercisesRoutines = nil
		o.R.Loaded.GroupExercisesRoutines = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	routineGroupByKey := make(map[uuid.UUID][]*RoutineGroup, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		routineGroupByKey[o.ID] = append(routineGroupByKey[o.ID], o)
	}

	for _, rel := range exercisesRoutines {

		owners, ok := routineGroupByKey[rel.GroupID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.GroupRoutineGroup = o
			rel.R.Loaded.GroupRoutineGroup = true

			o.R.GroupExercisesRoutines = append(o.R.GroupExercisesRoutines, rel)

		}
	}

	return nil
}

