// LoadRoutine loads the routineGroup's Routine into the .R struct
func (os RoutineGroupSlice) LoadRoutine(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	routines, err := os.Routine(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Routine = nil
		o.R.Loaded.Routine = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	routineGroupByKey := make(map[uuid.UUID][]*RoutineGroup, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		routineGroupByKey[o.RoutineID] = append(routineGroupByKey[o.RoutineID], o)
	}

	for _, rel := range routines {

		owners, ok := routineGroupByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Routine != nil {
				continue
			}

			rel.R.RoutineGroups = append(rel.R.RoutineGroups, o)

			o.R.Routine = rel

		}
	}

	return nil
}

